Below are the **only the parts that had to be changed** – the rest of the code can stay exactly as it was.

---

## 1. Server (C)

Only the `udp_server()` loop was rewritten so that it reads **pairs of integers** (event‑index, event‑value) from each UDP packet.  
All other code (socket creation, binding, libevdev setup) is unchanged.

```c
static void udp_server(void) {
    int sockfd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len = sizeof(cli_addr);
    char buffer[BUFFER_SIZE];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }

    while (1) {
        int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0,
                         (struct sockaddr *) &cli_addr, &cli_len);
        if (n < 0) {
            perror("ERROR in recvfrom");
            continue;
        }

        /* ---- NEW: process the packet as a sequence of (index,value) pairs ---- */
        int processed = 0;
        while (processed + 1 < n) {
            int event_index   = buffer[processed];
            int event_value  = buffer[processed + 1];

            if (event_index >= 0 &&
                event_index < sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0])) {
                libevdev_uinput_write_event(controller,
                    REGISTERED_EVENTS[event_index].type,
                    REGISTERED_EVENTS[event_index].code,
                    event_value);
                libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);
            }
            processed += 2;   /* advance to the next pair */
        }
        /* -------------------------------------------------------------------- */
    }

    close(sockfd);
}
```

---

## 2. Client (Zig)

### 2.1  New helper that sends a batch of **(index, value)** pairs

```zig
const NUM_EVENTS = 18;                     // ANALOG_LX … START
const BATCH_SIZE = NUM_EVENTS * 2 * @sizeOf(i16);

/// Sends a complete batch of (event_index, event_value) pairs.
fn sendEventBatch(sock: posix.fd_t,
                  addr: *const net.Address,
                  batch: [*const i16],
                  numEvents: usize) !void {
    const totalBytes = numEvents * 2 * @sizeOf(i16);
    var buffer: [BATCH_SIZE]i16 = undefined;          // stack‑allocated temp buffer
    @memcpy(buffer[0..totalBytes], batch);           // copy the pairs

    const sockaddr = &addr.any;
    const addrlen = addr.getOsSockLen();
    const ret = try posix.sendto(sock, buffer[0..totalBytes], 0, sockaddr, addrlen);
    if (ret != totalBytes) {
        std.log.warn("Warning: not all data was sent. Expected {} bytes, sent {}", totalBytes, ret);
    }
}
```

### 2.2  Updated main loop – build the pair batch and send it

```zig
pub fn main() anyerror!void {
    // … window setup …

    // Initialise the controller state (array of i16, one entry per event)
    var controllerState = initializeControllerState(); // length = NUM_EVENTS

    // Create a UDP socket for sending
    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    while (!rl.windowShouldClose()) {
        // ---- Update keyboard → controller state ----
        controllerState[@intFromEnum(ControllerEvents.UP)]    = if (rl.isKeyDown(rl.KeyboardKey.key_up))    1 else 0;
        controllerState[@intFromEnum(ControllerEvents.DOWN)]  = if (rl.isKeyDown(rl.KeyboardKey.key_down))  1 else 0;
        controllerState[@intFromEnum(ControllerEvents.LEFT)]  = if (rl.isKeyDown(rl.KeyboardKey.key_left))   1 else 0;
        controllerState[@intFromEnum(ControllerEvents.RIGHT)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;
        // (other events stay 0)

        // ---- Build the binary batch: (index, value) for every event ----
        var batch: [NUM_EVENTS * 2]i16 = undefined;
        var i: usize = 0;
        while (i < NUM_EVENTS) {
            batch[i * 2]     = @intCast(i);          // index = event position
            batch[i * 2 + 1] = controllerState[i];   // value   = current state
            i += 1;
        }

        // ---- Send the batch to the server ----
        const addr = try net.Address.parseIp4("127.0.0.1", 31415);
        try sendEventBatch(sock, &addr, &batch, NUM_EVENTS);

        // ---- Render the window (unchanged) ----
        rl.beginDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText("Press arrow keys to simulate controller input!", 190, 200, 20, rl.Color.light_gray);
        rl.endDrawing();
    }
}
```

### 2.3  (Optional) Keep the old `sendControllerState` – it is no longer used

If you leave it around, just delete or comment it out; the new `sendEventBatch` replaces it.

---

### What changed?

| Side | Old behaviour | New behaviour |
|------|---------------|---------------|
| **Server** | Read a single `(event_index, event_value)` pair from each UDP packet. | Reads the whole packet as a sequence of `(index, value)` pairs and processes each pair. |
| **Client** | Sent a flat array of `i16` values (no explicit indices). | Builds a binary buffer where each event is encoded as **two consecutive integers**: `index` followed by `value`, then sends that buffer. |

Both sides now speak the **same binary format**: a stream of 8‑byte blocks (`int32 index` + `int32 value`). The server can therefore correctly translate the incoming data into libevdev events, and the Zig client can drive the virtual joystick from keyboard input.

