## My answer to the prompt

A reliable approach is to measure the full text at the component’s available width, then show a separate “See more” control beside a one-line, truncated text. This keeps the control visible instead of placing it after text that may itself be truncated.

```tsx
import React, { useEffect, useState } from 'react';
import {
  LayoutChangeEvent,
  StyleProp,
  StyleSheet,
  Text,
  TextStyle,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';

type Props = {
  text: string;
  containerStyle?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
  moreLabel?: string;
  lessLabel?: string;
};

export default function ExpandableText({
  text,
  containerStyle,
  textStyle,
  moreLabel = 'See more',
  lessLabel = 'See less',
}: Props) {
  const [width, setWidth] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setExpanded(false);
    setHasMore(false);
  }, [text]);

  const onContainerLayout = (event: LayoutChangeEvent) => {
    const nextWidth = event.nativeEvent.layout.width;
    if (nextWidth !== width) setWidth(nextWidth);
  };

  return (
    <View style={containerStyle} onLayout={onContainerLayout}>
      {width > 0 && (
        <Text
          accessible={false}
          importantForAccessibility="no-hide-descendants"
          onTextLayout={({ nativeEvent }) =>
            setHasMore(nativeEvent.lines.length > 1)
          }
          style={[textStyle, styles.measurement, { width }]}
        >
          {text}
        </Text>
      )}

      {expanded ? (
        <View>
          <Text style={textStyle}>{text}</Text>
          {hasMore && (
            <TouchableOpacity
              accessibilityRole="button"
              onPress={() => setExpanded(false)}
            >
              <Text style={styles.link}>{lessLabel}</Text>
            </TouchableOpacity>
          )}
        </View>
      ) : (
        <View style={styles.collapsedRow}>
          <Text numberOfLines={1} style={[styles.collapsedText, textStyle]}>
            {text}
          </Text>
          {hasMore && (
            <TouchableOpacity
              accessibilityRole="button"
              onPress={() => setExpanded(true)}
            >
              <Text style={styles.link}>{moreLabel}</Text>
            </TouchableOpacity>
          )}
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  measurement: {
    position: 'absolute',
    left: 0,
    top: 0,
    opacity: 0,
  },
  collapsedRow: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  collapsedText: {
    flex: 1,
  },
  link: {
    color: '#007AFF',
    marginLeft: 6,
  },
});
```

The measured text uses the container’s width and the same text styling, so the “See more” control is only shown when the text wraps. The collapsed text gets less width to leave room for the control, and is truncated to one line.

